INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(1701, 'Exodus 9:16', 'Exodus', 9, 16, '&nbsp;خو ما تۀ د دې دپاره بادشاه کړې چې خپل طاقت ستا په ذريعه څرګند کړم او چې زما نوم په ټوله دُنيا کښې خور شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1702, 'Exodus 9:17', 'Exodus', 9, 17, '&nbsp;خو تر اوسه پورې تۀ خپل ځان ته لوئ ګورې او زما خلق تلو ته نۀ پرېږدې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1703, 'Exodus 9:18', 'Exodus', 9, 18, '&nbsp;ګوره، سبا دا وخت به زۀ ږلۍ ووروم، چې داسې ږلۍ به کله د مِصر په تاريخ کښې هم نۀ وى شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1704, 'Exodus 9:19', 'Exodus', 9, 19, '&nbsp;اوس خپل څاروى راولئ او چې په پټو کښې ستاسو نور څۀ هم وى هغه محفوظ ځائ ته راوړئ. ږلۍ به په بهر پاتې خلقو او ځناورو باندې ووريږى او ټول به مړۀ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1705, 'Exodus 9:20', 'Exodus', 9, 20, '&nbsp;د فِرعون کوم درباريان چې د مالِک خُدائ د خبرې نه يرېدل نو هغوئ خپل نوکران او څاروى په منډه باندې کورونو ته بوتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1706, 'Exodus 9:21', 'Exodus', 9, 21, '&nbsp;خو چا چې د مالِک خُدائ خبرو ته غوږ ونۀ نيولو نو هغوئ خپل نوکران او څاروى بهر په پټو کښې پرېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1707, 'Exodus 9:22', 'Exodus', 9, 22, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل، ”خپل لاس کښې امسا آسمان ته پورته کړه، نو د مِصر په ټول مُلک، خلقو، ځناورو او په پټو کښې په ټولو بوټو به ږلۍ ووريږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1708, 'Exodus 9:25', 'Exodus', 9, 25, '&nbsp;د مِصر په مُلک کښې بهر ټول ځناور او خلق ږلۍ ووهل. ږلۍ په پټو کښې ټول بوټى وغورزول او ټولې ونې يې ماتې کړلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1709, 'Exodus 9:26', 'Exodus', 9, 26, '&nbsp;خو صِرف د جشن په علاقه کښې، چرته چې بنى اِسرائيل اوسېدل، هلته لږه ږلۍ هم نۀ وه ورېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1710, 'Exodus 9:27', 'Exodus', 9, 27, '&nbsp;فِرعون موسىٰ او هارون راوغوښتل او ورته يې وفرمائيل، ”دا ځل زما نه ګناه شوې ده، مالِک خُدائ صادق دے او زۀ او زما خلق بدعمله يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1711, 'Exodus 9:28', 'Exodus', 9, 28, '&nbsp;مالِک خُدائ ته سوال وکړه. نور مونږ دې ږلۍ او تندرونو ته نۀ شُو ټينګېدے. زۀ به تاسو تلو ته پرېږدم، تاسو به دلته نور نۀ ايسارېږئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1712, 'Exodus 9:29', 'Exodus', 9, 29, '&nbsp;موسىٰ هغۀ ته وفرمائيل، ”زۀ چې څنګه د ښار نه لاړ شم، نو زۀ به د دُعا دپاره خپل لاسونه مالِک خُدائ ته پورته کړم. نو تندر به بس شى او نوره ږلۍ به نۀ وريږى، نو داسې به تا ته پته ولګى چې زمکه د مالِک خُدائ ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1713, 'Exodus 9:30', 'Exodus', 9, 30, '&nbsp;خو ما ته پته ده چې تۀ او ستا درباريان اوس هم د مالِک خُدائ، خُدائ پاک نه نۀ يرېږئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1714, 'Exodus 9:31', 'Exodus', 9, 31, '&nbsp;سنډ او اوربشې تباه شول، ځکه چې اوربشې پخې وې او د سنډو بوټى غوټۍ شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1715, 'Exodus 9:32', 'Exodus', 9, 32, '&nbsp;خو د غنمو فصل خراب نۀ شو، ځکه چې دا وروستو پخيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1716, 'Exodus 9:33', 'Exodus', 9, 33, '&nbsp;موسىٰ د فِرعون نه لاړو او د ښار نه بهر ووتلو او خپل لاسونه يې مالِک خُدائ ته پورته کړل. تندرونه، ږلۍ او باران هر څۀ ودرېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1717, 'Exodus 9:34', 'Exodus', 9, 34, '&nbsp;چې کله فِرعون ته پته ولګېده چې طوفان ختم شو، نو هغۀ بيا ګناه وکړه. هغۀ او د هغۀ درباريانو خپل زړونه سخت کړل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1718, 'Exodus 9:35', 'Exodus', 9, 35, '&nbsp;او لکه چې څنګه مالِک خُدائ د موسىٰ په ذريعه مخکښې فرمائيلى وُو، فِرعون بنى اِسرائيل تلو ته نۀ پرېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1719, 'Exodus 10:1', 'Exodus', 10, 1, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل، ”فِرعون له لاړ شه. ما د هغۀ او د هغۀ د درباريانو زړونه سخت کړى دى، چې زۀ په دوئ کښې خپلې دا معجزې څرګندې کړم', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1720, 'Exodus 10:2', 'Exodus', 10, 2, '&nbsp;او چې تاسو خپلو زامنو او نمسو ته وئيلے شئ چې کله ما معجزې څرګندې کړې نو ما د مِصريانو نه څنګه کم عقل جوړ کړل. تاسو ټولو ته به پته ولګى چې زۀ مالِک خُدائ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1721, 'Exodus 10:3', 'Exodus', 10, 3, '&nbsp;نو موسىٰ او هارون فِرعون له لاړل او هغۀ ته يې وفرمائيل، ”مالِک خُدائ، د عبرانيانو خُدائ پاک فرمائى چې، تۀ به تر کومې پورې زما د منلو نه اِنکار کوې؟ زما خلق تلو ته پرېږده، چې هغوئ زما عبادت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1722, 'Exodus 10:4', 'Exodus', 10, 4, '&nbsp;کۀ تۀ هم دغه شان اِنکار کوې، نو ګوره، سبا به زۀ ستا مُلک ته د قحطۍ مُلخان درولېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1723, 'Exodus 10:5', 'Exodus', 10, 5, '&nbsp;دا به دومره زيات وى چې د زمکې مخ به پټ کړى او هيڅ څوک به هم زمکه نۀ شى کتلے. دا به هغه هر څۀ وخورى کوم چې ږلۍ نۀ دى تباه کړى، دغه شان هغه ونې به هم وخورى چې بيا راشنې کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1724, 'Exodus 10:6', 'Exodus', 10, 6, '&nbsp;د قحطۍ مُولخانو نه به ستاسو کورونه، ستا د ټولو درباريانو او ستا د ټولو خلقو کورونه ډک شى. دا به د هغه هر څۀ نه بدتر وى چې کوم ستا پلار نيکۀ په تاريخ کښې ليدلى دى.“ بيا موسىٰ راوګرځېدو او د فِرعون نه لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1725, 'Exodus 10:7', 'Exodus', 10, 7, '&nbsp;د فِرعون درباريانو هغۀ ته ووئيل، ”دا سړے به تر کومې پورې مونږ له تکليف راکوى؟ دا خلق تلو ته پرېږده، نو چې دوئ د مالِک خُدائ، خپل خُدائ پاک عبادت وکړى. تا ته پته نۀ لګى چې مِصر تباه شو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1726, 'Exodus 10:8', 'Exodus', 10, 8, '&nbsp;نو موسىٰ او هارون واپس فِرعون له راوستے شول، نو هغۀ دوئ ته ووئيل، ”تاسو لاړ شئ او د مالِک خُدائ د خپل خُدائ پاک عبادت وکړئ. خو څوک څوک به ځى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1727, 'Exodus 10:9', 'Exodus', 10, 9, '&nbsp;نو موسىٰ ورته وفرمائيل، ”مونږ به ټول سره د خپلو ځوانانو او زړو ځُو. مونږ به د ځان سره خپل زامن، لوڼه، ګډې، چېلۍ او خپل څاروى هم بوځُو، ځکه چې مونږ به د مالِک خُدائ په درناوى کښې اختر کوُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1728, 'Exodus 10:10', 'Exodus', 10, 10, '&nbsp;فِرعون ووئيل، ”زما دې په مالِک خُدائ قسم وى چې زۀ به تاسو هيڅکله نۀ پرېږدم چې خپلې ښځې او بچى هم بوځئ. ګورئ، تاسو د څۀ غلط کار منصوبه جوړَوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1729, 'Exodus 10:11', 'Exodus', 10, 11, '&nbsp;نه، هيڅکله هم نه. کۀ تاسو د مالِک خُدائ عبادت کول غواړئ نو صِرف سړى تلے شى.“ نو موسىٰ او هارون د فِرعون د دربار نه وشړلے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1730, 'Exodus 10:12', 'Exodus', 10, 12, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل، ”خپل لاس اوږد کړه چې د مِصر په مُلک د قحطۍ مُلخان راشى. چې د قحطۍ مُلخان راشى نو هر يو شين بوټے به وخورى، هر هغه څيز چې د ږلۍ نه بچ پاتې وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1731, 'Exodus 10:13', 'Exodus', 10, 13, '&nbsp;نو موسىٰ خپله امسا اوږده کړه او مالِک خُدائ د نمرخاتۀ طرف نه په هغه مُلک باد راولېږلو چې په هغه ټوله شپه او ټوله ورځ وچلېدو. چې کله سحر شو نو دې باد د قحطۍ مُلخان راوړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1732, 'Exodus 10:14', 'Exodus', 10, 14, '&nbsp;د قحطۍ دې مُولخانو د مِصر ټول مُلک نيولے وو. دا د قحطۍ د مُولخانو د ټولو نه غټ لښکر وو چې نۀ د دې نه مخکښې ليدلے شوے وو او نۀ به بيا کله وليدلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1733, 'Exodus 10:15', 'Exodus', 10, 15, '&nbsp;دوئ د زمکې ټول مخ پټ کړو چې د دوئ په وجه مُلک تک تور شو، دوئ هغه هر څۀ وخوړل کوم چې د ږلۍ نه پاتې وُو، سره د هغه مېوې چې په ونو کښې وې. د مِصر ټول مُلک په ونو او بوټو کښې هيڅ يو شين څيز پاتې نۀ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1734, 'Exodus 10:16', 'Exodus', 10, 16, '&nbsp;نو فِرعون سمدستى موسىٰ او هارون راوغوښتل او ورته يې ووئيل، ”ما د مالِک خُدائ، ستاسو خُدائ پاک او ستاسو خِلاف ګناه کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1735, 'Exodus 10:17', 'Exodus', 10, 17, '&nbsp;نو اوس دا يو ځل زما ګناه معاف کړه او مالِک خُدائ خپل خُدائ پاک ته سوال وکړه چې دا د مرګ افت زما نه لرې کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1736, 'Exodus 10:18', 'Exodus', 10, 18, '&nbsp;موسىٰ د فِرعون نه لاړو او مالِک خُدائ ته يې سوال وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1737, 'Exodus 10:19', 'Exodus', 10, 19, '&nbsp;او مالِک خُدائ هغه د نمرخاتۀ باد په يو زورَور نمرپرېواتۀ باد بدل کړو، چې ټول د قحطۍ مُلخان يې اوچت کړل او بحرِقُلزم ته يې يوړل. د مِصر په مُلک کښې يو د قحطۍ مُلخ هم پاتې نۀ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1738, 'Exodus 10:20', 'Exodus', 10, 20, '&nbsp;خو مالِک خُدائ د فِرعون زړۀ سخت کړو او بنى اِسرائيل يې تلو ته نۀ پرېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1739, 'Exodus 10:21', 'Exodus', 10, 21, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل، ”خپل لاس آسمان طرف ته اوږد کړه، نو د مِصر په ټول مُلک به تيارۀ راشى، داسې تکه توره تيارۀ چې چا ته به هيڅ هم نۀ ښکارى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1740, 'Exodus 10:22', 'Exodus', 10, 22, '&nbsp;موسىٰ خپل لاس آسمان طرف ته اوچت کړو او درې ورځې په ټول مِصر تکه توره تيارۀ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1741, 'Exodus 10:23', 'Exodus', 10, 23, '&nbsp;مِصريانو تر درېو ورځو پورې يو بل نۀ شُو ليدلے او هيڅ څوک هم د خپل خپل ځائ نه ونۀ خوځېدل، خو چې په کوم ځائ کښې بنى اِسرائيل اوسېدل هلته رڼا وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1742, 'Exodus 10:24', 'Exodus', 10, 24, '&nbsp;فِرعون موسىٰ راوغوښتلو او ورته يې ووئيل، ”تاسو لاړ شئ چې د مالِک خُدائ عبادت وکړئ، هم دغه شان ستاسو ښځې او بچى هم درسره تلے شى. خو ستاسو ګډې، چېلۍ او څاروى به خامخا دلته پاتې کيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1743, 'Exodus 10:25', 'Exodus', 10, 25, '&nbsp;خو موسىٰ ورته وفرمائيل، ”تۀ به مونږ له څاروى راکوې چې مونږ يې د قربانيانو او سوزېدونکې نذرانې په توګه مالِک خُدائ خپل خُدائ پاک ته پېش کړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1744, 'Exodus 10:26', 'Exodus', 10, 26, '&nbsp;مونږ به خپل څاروى د ځان سره بوځُو، يو څاروے به هم نۀ پاتې کيږى. مونږ به په خپله څاروى خوښوو چې دې سره د مالِک خُدائ د خپل خُدائ پاک عبادت وکړُو. چې مونږ هلته رسېدلى نۀ يُو مونږ ته پته نۀ لګى چې د کومو څاروو قربانۍ هغۀ ته پېش کړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1745, 'Exodus 10:27', 'Exodus', 10, 27, '&nbsp;مالِک خُدائ د فِرعون زړۀ سخت کړو او دوئ يې تلو ته پرې نۀ ښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1746, 'Exodus 10:28', 'Exodus', 10, 28, '&nbsp;هغۀ موسىٰ ته ووئيل، ”د مخې نه مې ورک شه. نور چې زما وړاندې رانۀ شې. په کومه ورځ چې زما مخې ته راغلې نو مړ به شې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1747, 'Exodus 10:29', 'Exodus', 10, 29, '&nbsp;موسىٰ ورته وفرمائيل، ”ټيک ده، تا ښۀ ووئيل، تۀ به بيا ما کله هم ونۀ وينې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1748, 'Exodus 11:1', 'Exodus', 11, 1, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل، ”زۀ به د مِصر په فِرعون او د هغۀ په خلقو يو آخرى افت راولم. د هغې نه پس به هغه تاسو د دې ځائ نه تلو ته پرېږدى. په رښتيا سره، هغه به تاسو ټول د دې ځائ نه وباسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1749, 'Exodus 11:2', 'Exodus', 11, 2, '&nbsp;خلقو ته ووايه چې هر يو سړے د خپل ګاونډى نه او هره يوه ښځه به د خپلې ګاونډۍ نه د سپينو زرو او سرو زرو کالى وغواړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1750, 'Exodus 11:3', 'Exodus', 11, 3, '&nbsp;مالِک خُدائ بنى اِسرائيل د مِصريانو په نظر کښې درانۀ کړى دى. د دې نه علاوه، په خپله موسىٰ هم د مِصر په مُلک کښې د فِرعون د درباريانو او د ټولو خلقو په مخکښې يو عزتمند سړے ګڼلے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1751, 'Exodus 11:4', 'Exodus', 11, 4, '&nbsp;موسىٰ بيا فِرعون ته وفرمائيل، ”مالِک خُدائ فرمائى چې تقريباً په نيمه شپه به زۀ د مِصر نه تېر شم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1752, 'Exodus 11:5', 'Exodus', 11, 5, '&nbsp;د مِصر په مُلک کښې هر يو مشر زوئ به مړ شى، د فِرعون د مشر زوئ نه واخله کوم چې په تخت کښېنى د وينځې تر هغه مشر زوئ پورې کوم چې مېچنې ته ناست وى، او د څاروو ټول وړومبى پېدا شوى بچى به هم مړۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1753, 'Exodus 11:6', 'Exodus', 11, 6, '&nbsp;د مِصر په ټول مُلک کښې به داسې په زوره ژړا وى، چې نۀ به مخکښې کله شوې وى او نۀ به وشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1754, 'Exodus 11:7', 'Exodus', 11, 7, '&nbsp;خو چې چرته بنى اِسرائيل اوسيږى نو هلته به خېر وى، دوئ او د دوئ په څاروو پسې به يو سپے قدر هم ونۀ غپيږى. نو تا ته به پته ولګى چې زۀ، مالِک خُدائ د مِصريانو او بنى اِسرائيلو په مينځ کښې فرق راولم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1755, 'Exodus 11:8', 'Exodus', 11, 8, '&nbsp;موسىٰ خپله خبره د دې وئيلو سره ختمه کړه، ”ستا ټول درباريان به ما له راشى او زما په مخکښې به ټيټ شى او دوئ به زما مِنت وکړى چې خپل ټول خلق روان کړه او لاړ شه. د دې نه پس به زۀ لاړ شم.“ نو موسىٰ د قهره تک سور وو چې د فِرعون نه لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1756, 'Exodus 11:9', 'Exodus', 11, 9, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل، ”فِرعون به ستا خبره ځکه وانۀ ورى، چې زۀ د مِصر په مُلک کښې نورې معجزې هم وکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1757, 'Exodus 11:10', 'Exodus', 11, 10, '&nbsp;موسىٰ او هارون د فِرعون په مخکښې دا ټولې معجزې وکړې، خو مالِک خُدائ به د فِرعون زړۀ سختولو او هغۀ به بنى اِسرائيل د هغۀ د مُلک نه تلو ته نۀ پرېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1758, 'Exodus 12:1', 'Exodus', 12, 1, '&nbsp;مالِک خُدائ د مِصر په مُلک کښې موسىٰ او هارون ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1759, 'Exodus 12:2', 'Exodus', 12, 2, '&nbsp;”دا مياشت به ستاسو دپاره د کال اولنۍ مياشت وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1760, 'Exodus 12:3', 'Exodus', 12, 3, '&nbsp;د بنى اِسرائيلو ټول قوم ته دا ووايئ چې، د دې مياشتې په لسمه ورځ به هر سړے د خپل خاندان دپاره يو ګډُورے يا د چېلۍ بچے راولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1761, 'Exodus 12:4', 'Exodus', 12, 4, '&nbsp;او کۀ چرې د چا په خاندان کښې د ټول څاروى خوړلو والا کسان کم وى، نو هغه دې د خپل ګاونډى سره چې د هغۀ د کور په خوا کښې اوسيږى، په شريکه د کسانو د شمېر په مطابق ګډُورے يا د چېلۍ بچے راولى او هر يو کس ته دې د خوراک په مطابق حِصه مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1762, 'Exodus 12:5', 'Exodus', 12, 5, '&nbsp;تاسو به يو ګډُورے يا د چېلۍ بچے خوښ کړئ، خو دا دې خامخا د يو کال نر وى چې هيڅ عېب په کښې نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1763, 'Exodus 12:6', 'Exodus', 12, 6, '&nbsp;نو د دې مياشتې د څوارلسمې ورځې په ماښام، د بنى اِسرائيلو ټول قوم به دا څاروى حلال کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1764, 'Exodus 12:7', 'Exodus', 12, 7, '&nbsp;خلق دې د هغه وينې نه لږه وينه واخلى او د دروازو په چوکاټونو او پاسنۍ درشل باندې دې ولګوى، د کورونو په هغه چوکاټونو چرته چې هغوئ دا څاروى خورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1765, 'Exodus 12:8', 'Exodus', 12, 8, '&nbsp;په هغه شپه دې غوښه په اور وريته کړے شى او د ترخو بوټو او د پتيرې روټۍ سره دې وخوړلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1766, 'Exodus 12:9', 'Exodus', 12, 9, '&nbsp;د دې څاروى نه څۀ کچه او يا يشېدلې څيز مۀ خورئ، بلکې دا ټول وريت کړئ او سره د سر، پښو او دنننى ټولو اندامونه يې وخورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1767, 'Exodus 12:10', 'Exodus', 12, 10, '&nbsp;تر سحره پورې په دې کښې هيڅ هم باقى مۀ پرېږدئ، خو کۀ پاتې شى نو هغه وسوزوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1768, 'Exodus 12:11', 'Exodus', 12, 11, '&nbsp;دا به تاسو زر زر خورئ، ځکه چې تاسو به د سفر دپاره ملا تړئ، ستاسو په پښو به پېزار وى او ستاسو په لاسونو کښې به امساګانې وى. دا زما يعنې د مالِک خُدائ په درناوى کښې د فسحې اختر دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1769, 'Exodus 12:12', 'Exodus', 12, 12, '&nbsp;په هغه شپه به زۀ د مِصر مُلک نه تېرېږم او هر وړومبے پېدا شوے نر انسان او حېوان به ووژنم او د مِصر ټولو معبودانو له به سزا ورکړم، زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1770, 'Exodus 12:13', 'Exodus', 12, 13, '&nbsp;په چوکاټونو د وينې نښه به ما ته هغه کورونه په نښه کوى چې تاسو په کښې اوسېږئ. چې کله زۀ مِصريان هلاکوم او زۀ دې وينې ته ګورم، نو د څۀ نقصان رسولو نه بغېر به ستاسو نه تېر شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1771, 'Exodus 12:14', 'Exodus', 12, 14, '&nbsp;تاسو په دې ورځ خامخا اختر کوئ چې تاسو ته هغه څۀ درياديږى چې ما مالِک خُدائ څۀ کړى دى. دغه اختر په راتلونکى وختونو کښې همېشه دپاره کوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1772, 'Exodus 12:15', 'Exodus', 12, 15, '&nbsp;مالِک خُدائ وفرمائيل، ”تاسو به اووۀ ورځې خمبيره شوې پخه روټۍ نۀ خورئ، صِرف پتيره روټۍ به خورئ. په وړومبۍ ورځ به تاسو د خپلو کورونو نه ټوله خمبيره لرې کړئ، ځکه چې کۀ په دې اووۀ ورځو کښې څوک خمبيره شوې پخه روټۍ وخورى، نو هغه کس به د بنى اِسرائيلو نه نۀ شى ګڼلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1773, 'Exodus 12:16', 'Exodus', 12, 16, '&nbsp;په وړومبۍ ورځ او بيا په اوومه ورځ به تاسو زما د عبادت دپاره يو ځائ کېږئ. په دغه ورځو کښې به بل يو کار هم نۀ کوئ خو د ځان دپاره صِرف خوراک تيارولے شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1774, 'Exodus 12:17', 'Exodus', 12, 17, '&nbsp;د پتيرې روټۍ اختر کوئ، ځکه چې دا هغه ورځ ده چې ما تاسو د مِصر نه قبيله په قبيله راوويستلئ. تاسو به په راتلونکى وختونو کښې همېشه په دې ورځ اختر کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1775, 'Exodus 12:18', 'Exodus', 12, 18, '&nbsp;د وړومبۍ مياشتې د څوارلسمې ورځې د ماښام نه واخله د يويشتمې ورځې تر ماښامه پورې، خمبيره شوې روټۍ مۀ خورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1776, 'Exodus 12:21', 'Exodus', 12, 21, '&nbsp;موسىٰ د بنى اِسرائيلو ټول مشران راوغوښتل او هغوئ ته يې وفرمائيل، ”په تاسو کښې دې هر يو کس يو ګډُورے يا د چېلۍ بچے خوښ کړى او حلال يې کړئ، نو چې ستاسو خاندان د فسحې اختر وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1777, 'Exodus 12:22', 'Exodus', 12, 22, '&nbsp;د وېلنى يوه ګېډۍ راواخلئ، دا د وينې په لوښى کښې ډُوبه کړئ او دا وينه د خپلو کورونو د دروازو په چوکاټونو او په پاسنو دُرشلو باندې ولګوئ. په تاسو کښې دې يو کس هم د خپل کور نه تر سحره پورې نۀ وځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1778, 'Exodus 12:23', 'Exodus', 12, 23, '&nbsp;چې کله مالِک خُدائ د مِصر نه تېريږى او مِصريان هلاکوى، نو هغه به د دروازو په چوکاټونو او پاسنو دُرشلو باندې هغه وينه وګورى او د مرګ فرښته به ستاسو کورونو ته پرې نۀ ږدى چې راننوځى او تاسو ووژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
