(1781, 'Exodus 12:26', 'Exodus', 12, 26, '&nbsp;چې ستاسو اولاد ستاسو نه تپوس کوى چې، د دې اختر څۀ مطلب دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
