(1783, 'Exodus 12:28', 'Exodus', 12, 28, '&nbsp;بيا بنى اِسرائيل لاړل او هغه شان يې وکړل چې څنګه مالِک خُدائ موسىٰ او هارون له حُکم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1784, 'Exodus 12:29', 'Exodus', 12, 29, '&nbsp;په نيمه شپه کښې مالِک خُدائ د مِصر په مُلک کښې ټول وړومبى پېدا شوى زامن ووژل، د فِرعون د زوئ نه واخله کوم چې په تخت کښېناستو، د هغه قېدى د زوئ پورې چې په قېدخانې کښې وو، د څاروو ټول وړومبى پېدا شوى بچى هم ووژلے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1785, 'Exodus 12:30', 'Exodus', 12, 30, '&nbsp;په هغه شپه فِرعون، د هغۀ درباريان او نور ټول مِصريان راويښ شول. په ټول مِصر کښې په چغو چغو ژړا کېدله، ځکه چې يو کور هم داسې نۀ وو چې مړے په کښې نۀ وو شوے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1786, 'Exodus 12:31', 'Exodus', 12, 31, '&nbsp;هم په هغه شپه بادشاه موسىٰ او هارون راوغوښتل او ورته يې ووئيل، ”تاسو دواړه او ټول بنى اِسرائيل پاڅئ. زما د مُلک نه ووځئ، لکه څنګه چې تاسو وئيل، نو لاړ شئ او د مالِک خُدائ عبادت وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1787, 'Exodus 12:32', 'Exodus', 12, 32, '&nbsp;خپلې ګډې، چېلۍ او څاروى د ځان سره بوځئ او لاړ شئ. او زما د برکت دپاره هم دُعا وکړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1788, 'Exodus 12:33', 'Exodus', 12, 33, '&nbsp;مِصريانو په بنى اِسرائيلو زور راوړو چې زر زر د هغه مُلک نه ووځى، دوئ ووئيل، ”کۀ تاسو لاړ نۀ شئ نو مونږ به ټول مړۀ شُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1789, 'Exodus 12:34', 'Exodus', 12, 34, '&nbsp;نو خلقو د پتيرې پېړو ښانکونه ډک کړل او په څادرو کښې يې وتړل او د ځان سره يې يوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1790, 'Exodus 12:35', 'Exodus', 12, 35, '&nbsp;بنى اِسرائيلو هم هغسې کړى وُو چې څنګه موسىٰ ورته فرمائيلى وُو او د مِصريانو نه يې د سرو زرو او سپينو زرو کالى او جامې غوښتلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1791, 'Exodus 12:36', 'Exodus', 12, 36, '&nbsp;مالِک خُدائ په مِصريانو د دې خلقو قدر وکړو او چې دوئ څۀ غوښتل هغوئ ورکړل. نو داسې بنى اِسرائيلو د مِصريانو دولت لوټ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1792, 'Exodus 12:37', 'Exodus', 12, 37, '&nbsp;بنى اِسرائيلو د رعمسيس نه سُکات پورې پېدل مزل وکړو. د ښځو او ماشومانو نه بغېر دا تقريباً شپږ لاکه سړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1793, 'Exodus 12:38', 'Exodus', 12, 38, '&nbsp;سره د ډېرو ګډو، چېلو او څاروو، نور هم ډېر خلق ورسره لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1794, 'Exodus 12:39', 'Exodus', 12, 39, '&nbsp;دوئ د هغه پېړو نه پتيره روټۍ پخې کړې چې کومې يې د مِصر نه ځان سره راوړې وې، ځکه چې دوئ د مِصر نه ناڅاپى ويستلے شوى وُو چې دومره وخت ورته مِلاو نۀ شو چې د ځان دپاره خمبيره روټۍ يا نور خوراک تيار کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1795, 'Exodus 12:40', 'Exodus', 12, 40, '&nbsp;بنى اِسرائيل په مِصر کښې څلور سوه دېرش کاله اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1796, 'Exodus 12:41', 'Exodus', 12, 41, '&nbsp;هم په هغه ورځ څلور سوه دېرش کاله پوره شول، چې د مالِک خُدائ د خلقو ټولې قبيلې د مِصر نه ووتلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1797, 'Exodus 12:42', 'Exodus', 12, 42, '&nbsp;دا هغه شپه وه چې د مالِک خُدائ په دوئ نظر وو چې کله يې دوئ د مِصر نه راوويستل، نو دغه شپه به د همېشه دپاره مالِک خُدائ ته وقف وى نو ټول بنى اِسرائيل به په هم دې وجه په راتلونکى وخت کښې په دې شپه بېدار اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1798, 'Exodus 12:43', 'Exodus', 12, 43, '&nbsp;مالِک خُدائ موسىٰ او هارون ته وفرمائيل، ”دا د فسحې د اختر اصُول دى. د بل مُلک يو کس به هم د فسحې اختر خوراک نۀ خورى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1799, 'Exodus 12:44', 'Exodus', 12, 44, '&nbsp;خو چې کوم غلام تاسو په بيعه اخستے وى دا خوراک خوړلے شى خو تاسو به مخکښې هغه سنت کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1800, 'Exodus 12:45', 'Exodus', 12, 45, '&nbsp;مسافر يا مزدور به دا نۀ شى خوړلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');